<template>
	<view class="container">
		<!-- 顶部信息 -->
		<view class="header">
			<view class="avatar-section">
				<image class="avatar" :src="attendant.avatar || '/static/user-placeholder.png'"></image>
			</view>
			<view class="info-section">
				<text class="name">{{ attendant.name || '陪诊师' }}</text>
				<view class="certificate">
					<text class="certificate-text">{{ attendant.certificate || '专业陪诊师' }}</text>
				</view>
				<view class="rating">
					<text class="rating-text">★ {{ attendant.rating || 4.8 }}</text>
					<text class="service-count">已服务 {{ attendant.serviceCount || 100 }} 人次</text>
				</view>
			</view>
		</view>

		<!-- 基本信息 -->
		<view class="section">
			<view class="section-title">
				<text class="title-text">基本信息</text>
			</view>
			<view class="section-content">
				<view class="info-item">
					<text class="info-label">性别：</text>
					<text class="info-value">{{ attendant.sex || '未知' }}</text>
				</view>
				<view class="info-item">
					<text class="info-label">年龄：</text>
					<text class="info-value">{{ attendant.age || '未知' }}</text>
				</view>
				<view class="info-item">
					<text class="info-label">联系电话：</text>
					<text class="info-value">{{ attendant.phone || '未知' }}</text>
				</view>
				<view class="info-item">
					<text class="info-label">状态：</text>
					<text class="info-value">{{ attendant.status === 1 ? '在线' : '离线' }}</text>
				</view>
			</view>
		</view>
		
		<!-- 简介 -->
		<view class="section">
			<view class="section-title">
				<text class="title-text">个人简介</text>
			</view>
			<view class="section-content">
				<text class="intro-text">{{ attendant.introduction || '暂无简介' }}</text>
			</view>
		</view>

		<!-- 服务内容 -->
		<view class="section">
			<view class="section-title">
				<text class="title-text">服务内容</text>
			</view>
			<view class="section-content">
				<view class="service-item" v-for="(service, index) in services" :key="index">
					<text class="service-name">{{ service.name }}</text>
					<text class="service-desc">{{ service.description }}</text>
				</view>
			</view>
		</view>

		<!-- 底部按钮 -->
		<view class="bottom-bar">
			<button class="appointment-btn" @click="handleAppointment">预约陪诊</button>
		</view>
	</view>
</template>

<script setup>
import { ref, onMounted } from 'vue';
import { getAttendantById } from '../../api/attendant.js';

// 页面参数
const attendantId = ref('');
const attendantName = ref('');

// 陪诊师信息
const attendant = ref({
	id: '',
	name: '',
	certificate: '',
	introduction: '',
	avatar: '',
	rating: 4.8,
	serviceCount: 100,
	sex: '',
	age: '',
	phone: '',
	status: 0
});

// 服务内容（静态数据）
const services = ref([
	{
		name: '门诊陪诊',
		description: '陪同就医、挂号、排队、取药等全流程服务'
	},
	{
		name: '住院陪护',
		description: '住院期间的生活照料、陪同检查、沟通医生等服务'
	},
	{
		name: '手术陪同',
		description: '手术前准备、手术后照料、与医生沟通等服务'
	},
	{
		name: '远程问诊',
		description: '代为咨询医生、获取专业建议等服务'
	}
]);

// 获取陪诊师详情
const fetchAttendantDetail = async (id) => {
	try {
		const res = await getAttendantById(id);
		console.log('陪诊师详情:', res);
		if (res.code === 200 && res.data) {
			// 更新陪诊师信息
			attendant.value = {
				...attendant.value,
				id: res.data.id,
				name: res.data.name || attendantName.value || '陪诊师' + res.data.id,
				certificate: res.data.certificate || '专业陪诊师',
				introduction: res.data.introduction || '暂无简介',
				sex: res.data.sex || '未知',
				age: res.data.age || '未知',
				phone: res.data.phone || '未知',
				status: res.data.status,
				avatar: '/static/provider' + (res.data.id % 2 + 1) + '.jpg' // 使用默认头像
			};
			console.log('更新后的陪诊师信息:', attendant.value);
		} else {
			uni.showToast({
				title: '获取陪诊师详情失败',
				icon: 'none'
			});
		}
	} catch (error) {
		console.error('获取陪诊师详情出错:', error);
		uni.showToast({
			title: '网络错误，请稍后重试',
			icon: 'none'
		});
	}
};

// 预约按钮点击事件
const handleAppointment = () => {
	uni.navigateTo({
		url: `/subpkg/appointment/appointment-time?id=${attendant.value.id}&name=${encodeURIComponent(attendant.value.name)}`
	});
};

// 生命周期
onMounted(() => {
	const pages = getCurrentPages();
	const currentPage = pages[pages.length - 1];
	const options = currentPage.$page?.options;
	
	if (options) {
		attendantId.value = options.id;
		attendantName.value = options.name || '';
		console.log('页面参数:', options);
		
		// 如果有ID，获取详情
		if (attendantId.value) {
			fetchAttendantDetail(attendantId.value);
		} else {
			uni.showToast({
				title: '参数错误',
				icon: 'none'
			});
			setTimeout(() => {
				uni.navigateBack();
			}, 1500);
		}
	}
});
</script>

